export const modelStudioDefaults={scene3D:{schema:'motion-model-scene-v1',camera:{position:[5,3,8],target:[0,0,0],fov:42},lights:{ambient:.42,direction:[-.4,.8,.6],intensity:.65},nodes:[{id:'object-1',name:'Box',geometry:{kind:'box'},position:[0,0,0],rotation:[0,0,0],scale:[2,2,2],material:{color:'#a99cce'},animation:{spin:[0,20,0]}}]}};
